import type { ClaimFormValues } from '../claim-form/schema';
import { phoneDigits } from '../claim-form/schema';
import type { LossType, Province } from '../claim-form/options';
import type { components } from './generated/claims-api';

/*
 * Wire types come from the OpenAPI contract (claims-api/src/main/resources/openapi/claims-api.yaml),
 * generated by `npm run generate:api`. A contract change that breaks this client fails the type check.
 */
type Schemas = components['schemas'];
export type ClaimSubmissionRequest = Schemas['ClaimSubmissionRequest'];
export type ClaimSubmissionResponse = Schemas['ClaimSubmissionResponse'];
export type ServerFieldError = Schemas['FieldError'];

export type SubmitResult =
  | { kind: 'accepted'; claimNumber: string; submittedAt: string; message: string }
  | { kind: 'invalid'; errors: ServerFieldError[]; correlationId?: string }
  | { kind: 'failed'; correlationId?: string };

export type SubmitClaim = (values: ClaimFormValues) => Promise<SubmitResult>;

/**
 * Form values are flat for the form library; the API expects nested objects. Only call with values
 * that passed the form schema, which guarantees lossType and province are contract values.
 */
export function toRequest(values: ClaimFormValues): ClaimSubmissionRequest {
  const phone = phoneDigits(values.phone);
  return {
    customer: {
      firstName: values.firstName.trim(),
      lastName: values.lastName.trim(),
      email: values.email.trim(),
      ...(phone ? { phone } : {}),
    },
    policyNumber: values.policyNumber.trim().toUpperCase(),
    dateOfLoss: values.dateOfLoss,
    lossType: values.lossType as LossType,
    propertyAddress: {
      street: values.street.trim(),
      city: values.city.trim(),
      province: values.province as Province,
      postalCode: values.postalCode.trim().toUpperCase(),
    },
    description: values.description.trim(),
    consentAcknowledged: values.consentAcknowledged,
  };
}

/**
 * Submits the claim. Never throws: every outcome, including a network failure, is a result the
 * form can show. A per-submission X-Request-Id lets support find the request in the logs.
 */
export async function submitClaim(values: ClaimFormValues, fetchImpl: typeof fetch = fetch): Promise<SubmitResult> {
  const requestId = crypto.randomUUID();
  let response: Response;
  try {
    response = await fetchImpl('/api/v1/claims', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json', 'X-Request-Id': requestId },
      body: JSON.stringify(toRequest(values)),
    });
  } catch {
    return { kind: 'failed', correlationId: requestId };
  }

  const body = await readJson(response);
  const correlationId = stringField(body, 'correlationId') ?? response.headers.get('X-Request-Id') ?? requestId;

  if (response.status === 201 && body && typeof body.claimNumber === 'string') {
    return {
      kind: 'accepted',
      claimNumber: body.claimNumber,
      submittedAt: stringField(body, 'submittedAt') ?? '',
      message: stringField(body, 'message') ?? '',
    };
  }
  if (response.status === 400 && body && Array.isArray(body.errors)) {
    return { kind: 'invalid', errors: body.errors.filter(isFieldError), correlationId };
  }
  return { kind: 'failed', correlationId };
}

async function readJson(response: Response): Promise<Record<string, unknown> | null> {
  try {
    const parsed: unknown = await response.json();
    return parsed !== null && typeof parsed === 'object' ? (parsed as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

function stringField(body: Record<string, unknown> | null, name: string): string | undefined {
  const value = body?.[name];
  return typeof value === 'string' ? value : undefined;
}

function isFieldError(value: unknown): value is ServerFieldError {
  const candidate = value as ServerFieldError;
  return (
    candidate !== null &&
    typeof candidate === 'object' &&
    typeof candidate.field === 'string' &&
    typeof candidate.code === 'string' &&
    typeof candidate.message === 'string'
  );
}
